// === Tab: mySketch ===
//Define the particles and its numbers.
let Num = 200;
let particles = [];

//Create a mode for change random formula.
let mode;

function setup() {
  createCanvas(windowWidth, screen.availHeight);
  angleMode(DEGREES);
  background(0);

  //Turn on the mic.
  mic = new p5.AudioIn();
  mic.start();
  //Create a amplitude object.
  amplitude = new p5.Amplitude();
  //Set the input of the amplitude object.
  amplitude.setInput(mic);

  for (let a = 0; a < Num; a++) {
    particles.push(new Particle());
  }
  updateMode();
}

function draw() {
  for (let a = 0; a < particles.length; a++) {
    particles[a].show();
    particles[a].move();
  }
}

//Create a particle class that includes show and move functions, and change the x and y postion by using different formulas.
class Particle {
  constructor() {
    this.angle = 300 + random(-70, 70);
    this.speed = random(360);

    this.acceleration = random(0.25, 1.0)
  }

  show() {
    this.process(mode)

    //Change the points' color according to its position in the canvas.
    stroke(random(this.Xpos), random(this.Ypos), 200);

    //Change the points' size by audio input from mic.
    this.level = amplitude.getLevel();
    this.size = map(this.level, 0, 0.2, 1, 10);
    strokeWeight(this.size);

    point(this.Xpos, this.Ypos);
  }

  move() {
    this.speed += this.acceleration;
  }

  process(mode) {
    switch (mode) {
      case 0:
        //This formula is nspired by reona396's original code, and the web is shown below.
        //https://www.openprocessing.org/sketch/776044
        this.Xpos = width / 2 + (this.angle * sqrt(2) * cos(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * sqrt(2) * sin(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      //Formulas are inspired by http://www.felixauer.com/javascript/difeqrk.html
      case 1:
        this.Xpos = width / 2 + (this.angle * 0.5 * cos(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * 0.5 * cos(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 2:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * cos(-this.speed)) / (sq(sin(-this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * sqrt(2) * cos(-this.speed) * sin(-this.speed)) / (sq(sin(-this.speed)) + 1);
        break;

      case 3:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * sqrt(2) * sin(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 4:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * sqrt(2) * cos(this.speed) * cos(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 5:
        this.Xpos = width / 2 + (this.angle * sqrt(3) * cos(this.speed)) / (sq(cos(this.speed)) + 1);
        this.Ypos = height / 2 + (this.angle * sqrt(3) * cos(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 6:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * cos(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 - (this.angle * sqrt(2) * sin(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 7:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 - (this.angle * sqrt(2) * cos(this.speed) * cos(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 8:
        this.Xpos = width / 2 + (this.angle * sqrt(2) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        this.Ypos = height / 2 - (this.angle * sqrt(2) * sin(this.speed) * sin(this.speed)) / (sq(sin(this.speed)) + 1);
        break;

      case 9:
        this.Xpos = width / 2 + sin(this.speed) * 200;
        this.Ypos = height / 2 + cos(this.speed * this.Xpos) * 200;
        break;

      case 10:
        this.Xpos = width / 2 + cos(this.speed) * 500;
        this.Ypos = height / 2 + sin(this.Xpos) * cos(this.angle) * 500;
        break;

      case 11:

        this.Xpos = cos(this.angle) / sin(this.speed += this.acceleration) * 800;
        this.Ypos = height / 2 + cos(this.Xpos) * this.speed;
        break;

      //If there is no valid data, it will return to default formula which is a circle.
      default:
        this.Xpos = width / 2 + sin(this.speed) * 300;
        this.Ypos = height / 2 + cos(this.speed) * 300;
        break;
    }
  }
}

//Change to random mode by clicking mouse.
function updateMode() {
  mode = floor(random(0, 12));
}

function mousePressed() {
  updateMode()
}

//Restart the project by hitting the up arrow.
function keyPressed() {
  if (keyCode === UP_ARROW) {
    setup();
  }else{
		save('pix.jpg');
  }
  //Prevent default.
  return false;
}

